// CPU actual-dispatch fixture. Main compiles/runs; no model/GPU/driver/runtime linkage.
#include "strata/core/expert_source.hpp"
#include "strata/kernels/cpu/expert_layout.hpp"
#include "ggml.h"
#include <algorithm>
#include <array>
